//
//Insert a polyline into the CDT object, the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	isclosed: if true, it is closed, if false, it is open.
//
void insertConstraintPolyline(const Vector_Point vp, const bool isclosed){
	Vertex_handle vt1;
	Vertex_handle vt2;
	int n =  vp.size();
	for (int i = 0; i < n-1; i++){
		vt1 = cdt.insert(vp[i]);
		vt2 = cdt.insert(vp[i+1]);
		cdt.insert_constraint(vt1, vt2);
	}
	if (n > 2 && isclosed){
		vt1 = cdt.insert(vp[n-1]);
		vt2 = cdt.insert(vp[0]);
		cdt.insert_constraint(vt1, vt2);
	}
}

//
//Insert a polyline with distance input for every segment into the CDT object,
//the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	vd: double vector to define the point distribution interval in every segment
//	isclosed: if true, it is closed, if false, it is open.
//
void insertConstraintPolyline(const Vector_Point vp, const Vector_double vd, const bool isclosed){
	int seg_n;
	double seg_l, seg_d, delt_x, delt_y;
	int n =  vp.size();
	for (int i = 0; i < n-1; i++){
		seg_l = sqrt(pow(vp[i+1].x()-vp[i].x(),2)+pow(vp[i+1].y()-vp[i].y(),2));
		seg_d = vd[i];
		seg_n = ceil(seg_l/seg_d);
		delt_x = (vp[i+1].x()-vp[i].x())/seg_n;
		delt_y = (vp[i+1].y()-vp[i].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[i].x(),vp[i].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[i].x()+delt_x*j,vp[i].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[i+1].x(),vp[i+1].y()));
		insertConstraintPolyline(seg_pts, false);
	}
	if (n > 2 && isclosed){
		seg_l = sqrt(pow(vp[0].x()-vp[n-1].x(),2)+pow(vp[0].y()-vp[n-1].y(),2));
		seg_d = vd[n-1];
		seg_n = ceil(seg_l/seg_d);
		delt_x = (vp[0].x()-vp[n-1].x())/seg_n;
		delt_y = (vp[0].y()-vp[n-1].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[n-1].x(),vp[n-1].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[n-1].x()+delt_x*j,vp[n-1].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[0].x(),vp[0].y()));
		insertConstraintPolyline(seg_pts, false);
	}
}

//
//Insert a polyline with distance input for every segment into the CDT object,
//the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	vi: integer vector to define the number of interval in every segment
//	isclosed: if true, it is closed, if false, it is open.
//
void insertConstraintPolyline(const Vector_Point vp, const Vector_int vi, const bool isclosed){
	int seg_n;
	double seg_l, delt_x, delt_y;
	int n =  vp.size();
	for (int i = 0; i < n-1; i++){
		seg_l = sqrt(pow(vp[i+1].x()-vp[i].x(),2)+pow(vp[i+1].y()-vp[i].y(),2));
		seg_n = vi[i];
		delt_x = (vp[i+1].x()-vp[i].x())/seg_n;
		delt_y = (vp[i+1].y()-vp[i].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[i].x(),vp[i].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[i].x()+delt_x*j,vp[i].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[i+1].x(),vp[i+1].y()));
		insertConstraintPolyline(seg_pts, false);
	}
	if (n > 2 && isclosed){
		seg_l = sqrt(pow(vp[0].x()-vp[n-1].x(),2)+pow(vp[0].y()-vp[n-1].y(),2));
		seg_n = vi[n-1];
		delt_x = (vp[0].x()-vp[n-1].x())/seg_n;
		delt_y = (vp[0].y()-vp[n-1].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[n-1].x(),vp[n-1].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[n-1].x()+delt_x*j,vp[n-1].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[0].x(),vp[0].y()));
		insertConstraintPolyline(seg_pts, false);
	}
}

//
//Calculate equation of circle given 3 points
//Description of variables
//  (x1, y1), (x2, y2), and (x3, y3): the given 3 points
//  (x0, y0): calculated center point
//  r: calculated radius
//
int calculateCircle3Points(const double x1, const double y1, const double x2, const double y2,
		const double x3, const double y3, double &x0, double &y0, double &r){
	double zero = 0.0;
	double x1y1 = x1*x1+y1*y1;
	double x2y2 = x2*x2+y2*y2;
	double x3y3 = x3*x3+y3*y3;
	double x0det = x1*(y3-y2)+x2*(y1-y3)+x3*(y2-y1);
	double y0det = y1*(x3-x2)+y2*(x1-x3)+y3*(x2-x1);

	if (x0det == zero || y0det == zero) return 0;

	x0 = 0.5*(x1y1*(y3-y2) + x2y2*(y1-y3) + x3y3*(y2-y1))/x0det;
	y0 = 0.5*(x1y1*(x3-x2) + x2y2*(x1-x3) + x3y3*(x2-x1))/y0det;
	r = sqrt((x1-x0)*(x1-x0) + (y1-y0)*(y1-y0));

	return 1;
}

//
//Calculate the angle in Cartesian coordinates based on the cosine and sine value
//Description of variables
//  cosangle: input cosine value of the angle
//  sinangle: input sine value of the given angle
//  calculateAngle: return the angle in Cartesian coordinates [0-2Pi)
//
double calculateAngle(const double cosangle, const double sinangle){
	double angle = 0.0;
	double pi = 3.141592653589793;
	if(cosangle >= 0 && sinangle >= 0)     //quadrant 1
		angle = asin(sinangle);
	else if(cosangle < 0 && sinangle >= 0) //quadrant 2
		angle = pi - asin(sinangle);
	else if(cosangle < 0 && sinangle < 0)  //quadrant 3
		angle = pi - asin(sinangle);
	else if(cosangle >= 0 && sinangle < 0)  //quadrant 4
		angle = 2.0*pi + asin(sinangle);
	return angle;
}

//
//Check the direction of the given 3 points, return true if it is counter-clockwise,
//  return false if it is clockwise
//Description of variables
//  (x1, y1), (x2, y2), and (x3, y3): the given 3 points
//  isCounterClockwise: true if the given 3 points are counter-clockwise, otherwise, false
//
bool isCounterClockwise(const double x1, const double y1, const double x2, const double y2,
		const double x3, const double y3){
	double area = ((x2-x1)*(y3-y1)-(x3-x1)*(y2-y1))*0.5;
	if (area > 0.0)
		return true;
	else
		return false;
}

//
//Partition Arc to small ones based on the given interval
//Description of variables
//  (x1, y1) and (x2, y2): the beginning and end point of the arc
//  (x0, y0): the center point of the arc (circle)
//  r: radius of the arc (circle)
//  isCounter: direction of the arc, if true, it is couter-clockwise, otherwise, clockwise
//  delt_arc: the given interval (arc length)
//  vp: returned internal vertices, without the beginning and end point
//
void partitionArcPoints(const double x1, const double y1, const double x2, const double y2,
		const double x0, const double y0, const double r, const bool isCounter,
		const double delt_arc, Vector_Point &vp){
	//convert Cartesian coordinates to Polar coordinates
	double pi = 3.141592653589793;
	double xx1 = x1 - x0;
	double yy1 = y1 - y0;
    double xx2 = x2 - x0;
    double yy2 = y2 - y0;
    double cos1 = xx1/r;
    double sin1 = yy1/r;
    double cos2 = xx2/r;
    double sin2 = yy2/r;
    double angle1 = calculateAngle(cos1, sin1);
    double angle2 = calculateAngle(cos2, sin2);

    if (isCounter){
    	if (angle2 < angle1){
    		angle2 = 2.0*pi + angle2;
    	}
    }
    else{
    	if (angle2 > angle1){
    		angle2 = -2.0*pi + angle2;
    	}
    }

    double angle = angle2 - angle1;
    double arclen = fabs(angle*r);
    int n = ceil(arclen/delt_arc);
    double delt_angle = angle/n;

    double x, y;
    for (int i = 1; i < n; i++){
    	x = r*cos(angle1+delt_angle*i)+x0;
    	y = r*sin(angle1+delt_angle*i)+y0;
    	vp.push_back(Point(x,y));
    }

}

//
//Insert circle or arc into CDT object
//Description of variables
//  pt1, pt2 and pt3 are the given 3 points
//  delt_arc: the given interval (arc length)
//  isClosed: if true, this is a circle, otherwise, it's an arc in the direction pt1->pt2->pt3
//
void insertConstraintCircle(const Point pt1, const Point pt2, const Point pt3,
		const double delt_arc, const bool isClosed){

	double x0, y0, r;
	Vector_Point vp;

	bool isCounter = isCounterClockwise(pt1.x(), pt1.y(), pt2.x(), pt2.y(), pt3.x(), pt3.y());

	int iflag = calculateCircle3Points(pt1.x(), pt1.y(), pt2.x(), pt2.y(),
			pt3.x(), pt3.y(), x0, y0, r);

	if (iflag > 0){
		vp.push_back(pt1);
		partitionArcPoints(pt1.x(), pt1.y(), pt2.x(), pt2.y(),
				x0, y0, r, isCounter, delt_arc, vp);
		vp.push_back(pt2);
		partitionArcPoints(pt2.x(), pt2.y(), pt3.x(), pt3.y(),
				x0, y0, r, isCounter, delt_arc, vp);
		vp.push_back(pt3);
		if (isClosed)
			partitionArcPoints(pt3.x(), pt3.y(), pt1.x(), pt1.y(),
					x0, y0, r, isCounter, delt_arc, vp);

		insertConstraintPolyline(vp, isClosed);
	}

}

//
//Set seeds for mesh generation
//Description of variables
//  mesher: input Delaunay_mesher_2
//	vp: Point vector to construct the list of seds
//
void setSeeds(const Vector_Point vp){
	std::list<Point> list_of_seeds;
	int n =  vp.size();
	for (int i = 0; i < n; i++){
		list_of_seeds.push_back(Point(vp[i].x(),vp[i].y()));
	}
	mesher.set_seeds(list_of_seeds.begin(),list_of_seeds.end());
}

//
//Set criteria for mesh generation
//Description of variables
//  mesher: input Delaunay_mesher_2
//  shape_bound: the shape criterion that bounds the minimum angle of triangles, it corresponds to about 20.6 degree
//  max_edge: the upper bound on the length of the longest edge
//
void setCriteria(const double shape_bound, const double max_edge){
	mesher.set_criteria(Criteria(shape_bound,max_edge));
}

//
// 2d triangulation coordinate type
//
void setCoordinateType(const int itype){
	itypeCoordinate = itype;
}

//
//Make/refine mesh using constrained delaunay triangulation
//Description of variables
//  mesher: input Delaunay_mesher_2
//
void refineMesh(){
	mesher.refine_mesh();

	mesh_vertices_counter = cdt.number_of_vertices();

	cout << "Number of vertices " << mesh_vertices_counter << endl;

	mesh_edges_counter = 0;
	for (CDT::Finite_edges_iterator eit = cdt.finite_edges_begin();
	      eit != cdt.finite_edges_end();++eit){
	   if (cdt.is_constrained(*eit)) ++mesh_edges_counter;
	}

	cout << "Number of edges " << mesh_edges_counter << endl;

	mesh_faces_counter = 0;
	for(CDT::Finite_faces_iterator fit = cdt.finite_faces_begin();
	    fit != cdt.finite_faces_end(); ++fit)
	{
	  if(fit->is_in_domain()) ++mesh_faces_counter;
	}

	cout << "Number of faces " << mesh_faces_counter << endl;
}

//
//Optimize mesh using lloyd_optimize_mesh_2 method
//Description of variables
//  mesher: input Delaunay_mesher_2
//  cdt: Constrained_Delaunay_triangulation_2 object.
//  iteration: maximum iteration number for lloyd_optimize_mesh_2
//
void optimizeMesh(const int iteration){
	CGAL::lloyd_optimize_mesh_2(cdt,
			CGAL::parameters::max_iteration_number = iteration,
			CGAL::parameters::seeds_begin = mesher.seeds_begin(),
			CGAL::parameters::seeds_end = mesher.seeds_end());
}

//
//Output mesh to file
//Description of variables
//  nfile: length of file path
//  sfile: file path
//  nformat: length of file format
//  sformat: file format, 'msh' or 'off'
//
void outputMesher(const int nfile,const char* sfile,
		const int nformat, const char* sformat){

	  std::string strfile(sfile,0,nfile);
	  std::string strformat(sformat,0,nformat);

	  // Output mesh 2D
	  std::ofstream out;

	  // Output the mesh to OFF (Object File Format)
	  out.open(strfile);

	  // Vertices list with index
	  std::map<Point, int> map_vts;

	  //Note: index in off file is 0-based and msh file format is 1-based
	  int icell = 0;
	  int ivertex = 0;

	  //

	  if (strformat == "off"){
		  //Note: index in off file format is 0-based
	      // Write header
	      out << "OFF" << endl;

	      //Off file head information
		out << mesh_vertices_counter << " "
        		  << mesh_faces_counter << " "
				  << mesh_edges_counter << endl;

          //Write vertex
		  for(CDT::Finite_vertices_iterator vit = cdt.finite_vertices_begin();
		  	  vit != cdt.finite_vertices_end(); ++vit){
			Point pt = vit->point();
			map_vts[pt] = ivertex;
			ivertex = ivertex + 1;
			if(itypeCoordinate == 0){
				out << pt.x() << " " << pt.y() << " " << " 0" << endl;
			}
			else if(itypeCoordinate == 1){
				out << " 0 " << pt.x() << " " << pt.y() << endl;
			}
			else if(itypeCoordinate == 0){
				out << pt.x() << " 0 " << pt.y() << endl;
			}
		  }

		  //Write faces
		  for(CDT::Finite_faces_iterator fit = cdt.finite_faces_begin();
		          fit != cdt.finite_faces_end(); ++fit){
		    if(fit->is_in_domain()){
		        //Write 3-node triangles
		        Point pt0 = fit->vertex(0)->point();
		        Point pt1 = fit->vertex(1)->point();
		        Point pt2 = fit->vertex(2)->point();
	            out << "3 " << map_vts[pt0] << " "
			            << map_vts[pt1] << " " << map_vts[pt2] << endl;
		    }
		  }
	  }
	  else if (strformat == "msh"){
		  //Note: index in msh file format is 1-based
		  // Output the mesh to file

		  // Write header
		  out << "$MeshFormat" << endl;
		  out << "2.2 0 8" << endl;
		  out << "$EndMeshFormat" << endl;
		  //Write nodes/vertices
		  out << "$Nodes" << endl;
		  out << mesh_vertices_counter << endl;
		  for(CDT::Finite_vertices_iterator vit = cdt.finite_vertices_begin();
		  	  vit != cdt.finite_vertices_end(); ++vit){
			Point pt = vit->point();
			ivertex = ivertex + 1;
			map_vts[pt] = ivertex;
			if(itypeCoordinate == 0){
				out << map_vts[pt] << " " << pt.x() << " " << pt.y() << " " << " 0" << endl;
			}
			else if(itypeCoordinate == 1){
				out << map_vts[pt] << " 0 " << pt.x() << " " << pt.y() << endl;
			}
			else if(itypeCoordinate == 2){
				out << map_vts[pt] << " " << pt.x() << " 0 " << pt.y() << endl;
			}
		  }
		  out << "$EndNodes" << endl;

		  // Write elements/cells
		  out << "$Elements" << endl;
		  out << mesh_faces_counter << endl;
		  for(CDT::Finite_faces_iterator fit = cdt.finite_faces_begin();
		          fit != cdt.finite_faces_end(); ++fit){
		    if(fit->is_in_domain()){
		    	icell = icell + 1;
		        //Write 3-node triangles, tags are set to 2 with tag value 0, hardwired
		        Point pt0 = fit->vertex(0)->point();
		        Point pt1 = fit->vertex(1)->point();
		        Point pt2 = fit->vertex(2)->point();
		    	out << icell << " 2 2 0 0 " << map_vts[pt0] << " "
		            << map_vts[pt1] << " " << map_vts[pt2] << endl;
		    }
		  }
		  out << "$EndElements" << endl;
	  }
	  else if (strformat == "vtk"){
		  //Note: index in vtk file format is 0-based
		  // Output the mesh to file

		  // Write header
		  out << "# vtk DataFile Version 2.0" << endl;
		  out << "CGAL constrained delaunay mesh generation 2d" << endl;
		  out << "ASCII" << endl;
		  out << "DATASET UNSTRUCTURED_GRID" << endl;

		  //Write nodes/vertices
		  out << "POINTS " << mesh_vertices_counter << " double" << endl;

		  for(CDT::Finite_vertices_iterator vit = cdt.finite_vertices_begin();
		  	  vit != cdt.finite_vertices_end(); ++vit){
			Point pt = vit->point();
			map_vts[pt] = ivertex;
			ivertex = ivertex + 1;
			if(itypeCoordinate == 0){
				out << pt.x() << " " << pt.y() << " " << " 0" << endl;
			}
			else if(itypeCoordinate == 1){
				out << "0 " << pt.x() << " " << pt.y() << endl;
			}
			else if(itypeCoordinate == 2){
				out << pt.x() << " 0 " << pt.y() << endl;
			}
		  }
		  out << endl;

		  // Write elements/cells
		  out << "CELLS " << mesh_faces_counter << " " << mesh_faces_counter*4 << endl;

		  for(CDT::Finite_faces_iterator fit = cdt.finite_faces_begin();
		          fit != cdt.finite_faces_end(); ++fit){
		    if(fit->is_in_domain()){
		        //Write 3-node triangles, tags are set to 2 with tag value 0, hardwired
		        Point pt0 = fit->vertex(0)->point();
		        Point pt1 = fit->vertex(1)->point();
		        Point pt2 = fit->vertex(2)->point();
		    	out << "3 " << map_vts[pt0] << " " << map_vts[pt1] << " "
		    			<< map_vts[pt2] << endl;
		    }
		  }
		  out << endl;

		  // Write cell type
		  out << "CELL_TYPES " << mesh_faces_counter << endl;

	      for (int iface = 0; iface < mesh_faces_counter; iface++){
	    	  out << "5" << endl;
	      }
		  out << endl;
	  }
	  else{
		  out << "Error: output mesh format is unknown" << endl;
	  }
	  // Close file
	  out.close();
}

extern  "C" {

// set temporatory points vector served as bridge between C++ and Fortran
void set_vector_point_temp_2d(const int n, const point2d * pts){
	vector_point_temp.clear();
	for (int i = 0; i < n; i++){
		vector_point_temp.push_back(Point((pts+i)->x,(pts+i)->y));
	}
}

// set temporatory double vector served as bridge between C++ and Fortran
void set_vector_double_temp(const int n, const double * dvalue){
	vector_double_temp.clear();
	for (int i = 0; i < n; i++){
		vector_double_temp.push_back(dvalue[i]);
	}
}

// set temporatory integer vector served as bridge between C++ and Fortran
void set_vector_int_temp(const int n, const int * ivalue){
	vector_int_temp.clear();
	for (int i = 0; i < n; i++){
		vector_int_temp.push_back(ivalue[i]);
	}
}

//
//Insert a polyline into the CDT object, the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	isclosed: if true, it is closed, if false, it is open.
//
void insert_constraint_polyline_2d(const Vector_Point vp, const bool isclosed){
	insertConstraintPolyline(vp, isclosed);
}

//
//Same as insert_constraint_polyline except use the temporatory global variable
//It's best to directly pass variables from Fortran to C++, however, vector or array
//as dummy variables are only supported in the latest Fortran compiler (2015 or later)
//
void insert_constraint_polyline_2d_ex(const bool isclosed){
	insertConstraintPolyline(vector_point_temp, isclosed);
}

//
//Insert a polyline with distance input for every segment into the CDT object,
//the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	vd: double vector to define the point distribution interval in every segment
//	isclosed: if true, it is closed, if false, it is open.
//
void insert_constraint_polyline_2d_d(const Vector_Point vp,
		const Vector_double vd, const bool isclosed){
	insertConstraintPolyline(vp, vd, isclosed);
}

//
//Same as insert_constraint_polyline_d except use the temporatory global variable
//It's best to directly pass variables from Fortran to C++, however, vector or array
//as dummy variables are only supported in the latest Fortran compiler (2015 or later)
//
void insert_constraint_polyline_2d_d_ex(const bool isclosed){
	insertConstraintPolyline(vector_point_temp, vector_double_temp, isclosed);
}

//
//Insert a polyline with distance input for every segment into the CDT object,
//the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	vi: integer vector to define the number of interval in every segment
//	isclosed: if true, it is closed, if false, it is open.
//
void insert_constraint_polyline_2d_n(const Vector_Point vp,
		const Vector_int vi, const bool isclosed){
	insertConstraintPolyline(vp, vi, isclosed);
}

//
//Same as insert_constraint_polyline_n except use the temporatory global variable
//It's best to directly pass variables from Fortran to C++, however, vector or array
//as dummy variables are only supported in the latest Fortran compiler (2015 or later)
//
void insert_constraint_polyline_2d_n_ex(const bool isclosed){
	insertConstraintPolyline(vector_point_temp, vector_int_temp, isclosed);
}

//
//Insert circle or arc into CDT object
//Description of variables
//  pt1, pt2 and pt3 are the given 3 points
//  delt_arc: the given interval (arc length)
//  isClosed: if true, this is a circle, otherwise, it's an arc in the direction pt1->pt2->pt3
//  insertConstraintCircle: return true if internal vertices are added
//
void insert_constraint_circle_2d(const Point pt1, const Point pt2, const Point pt3,
		const double delt_arc, const bool isClosed){
	insertConstraintCircle(pt1, pt2, pt3, delt_arc, isClosed);
}

//
//Same as insert_constraint_circle except use the temporatory global variable
//It's best to directly pass variables from Fortran to C++, however, vector or array
//as dummy variables are only supported in the latest Fortran compiler (2015 or later)
//
void insert_constraint_circle_2d_ex(const double delt_arc, const bool isClosed){
	insertConstraintCircle(vector_point_temp[0], vector_point_temp[1],
			vector_point_temp[2], delt_arc, isClosed);
}

//Triangulation coordinate type
//0-xy coordinate
//1-yz coordinate
//2-xz coordinate
void set_coordinate_type_2d(const int itype){
	setCoordinateType(itype);
}

//
//Set seeds for mesh generation
//Description of variables
//  mesher: input Delaunay_mesher_2
//	vp: Point vector to construct the list of seds
//
void set_seeds_2d(const Vector_Point vp){
	setSeeds(vp);
}

//
//Same as set_seeds except use the temporatory global variable
//It's best to directly pass variables from Fortran to C++, however, vector or array
//as dummy variables are only supported in the latest Fortran compiler (2015 or later)
//
void set_seeds_2d_ex(){
	setSeeds(vector_point_temp);
}

//
//Set criteria for mesh generation
//Description of variables
//  mesher: input Delaunay_mesher_2
//  min_angle: the shape criterion that bounds the minimum angle of triangles, it corresponds to about 20.6 degree
//  max_edge: the upper bound on the length of the longest edge
//
void set_criteria_2d(const double min_angle,const double max_edge){
	setCriteria(min_angle,max_edge);
}

//
//Make/refine mesh using constrained delaunay triangulation
//Description of variables
//  mesher: input Delaunay_mesher_2
//
void refine_mesh_2d(){
	refineMesh();
}

//
//Optimize mesh using lloyd_optimize_mesh_2 method
//Description of variables
//  mesher: input Delaunay_mesher_2
//  cdt: Constrained_Delaunay_triangulation_2 object.
//  iteration: maximum iteration number for lloyd_optimize_mesh_2
//
void optimize_mesh_2d(const int iteration){
	optimizeMesh(iteration);
}

//
//Output mesh to file
//Description of variables
//  nfile: length of file path
//  sfile: file path
//  nformat: length of file format
//  sformat: file format, 'msh' or 'off'
//
void output_mesh_2d(const int nfile,const char* sfile,
		const int nformat, const char* sformat){
    outputMesher(nfile,sfile,nformat,sformat);
  }
}

